use anyhow::Result;
use axum::{
    routing::{get, post},
    Router, Json, response::Html, extract::State
};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::oneshot;
use tracing::info;

#[derive(Debug, Deserialize, Serialize, Clone)]
pub struct BootstrapPayload {
    pub role: String,
    pub cluster_token: Option<String>,
    pub server_url: Option<String>,
    pub gitlab_url: Option<String>,
    pub pod_cidr: Option<String>,
    pub service_cidr: Option<String>,
    pub node_ip: Option<String>,
    pub isolate_control_plane: Option<String>,
    pub hostname: String,
    pub ssh_keys: Option<String>,
}

#[derive(Debug, Serialize, Clone)]
pub struct BootstrapStatus {
    pub state: String,
    pub message: String,
}

// Shared state to allow the handler to trigger shutdown and update status
pub struct AppState {
    status: tokio::sync::RwLock<BootstrapStatus>,
    shutdown_tx: tokio::sync::Mutex<Option<oneshot::Sender<()>>>,
}

pub async fn start_server() -> Result<()> {
    let (tx, rx) = oneshot::channel();
    let state = Arc::new(AppState {
        status: tokio::sync::RwLock::new(BootstrapStatus {
            state: "pending".into(),
            message: "Waiting for configuration".into(),
        }),
        shutdown_tx: tokio::sync::Mutex::new(Some(tx)),
    });

    let app = Router::new()
        .route("/", get(web_ui))
        .route("/api/v1/bootstrap", post(handle_bootstrap))
        .route("/api/v1/bootstrap/status", get(handle_bootstrap_status))
        .route("/api/v1/network-info", get(handle_network_info))
        .route("/api/v1/network-route", post(handle_network_route))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:8080").await?;
    info!("Axum server listening on 0.0.0.0:8080");

    axum::serve(listener, app)
        .with_graceful_shutdown(async move {
            rx.await.ok();
        })
        .await?;

    info!("Axum server gracefully stopped after successful bootstrap.");
    Ok(())
}

